    @pytest.mark.sphinx(
        'linkcheck', testroot='linkcheck', freshenv=True,
        confoverrides={'linkcheck_anchors_disabled': [r'http://localhost:7777/.*']})
    def test_anchors_disabled(app):
        with http_server(DefaultsHandler):
            app.build()
        content = (app.outdir / 'output.txt').read_text(encoding='utf8')
        # looking for '#top' and '#does-not-exist' should now be ignored
        assert "Anchor 'top' not found" not in content
        assert "Anchor 'does-not-exist' not found" not in content
        # images should still fail
        assert "Not Found for url: http://localhost:7777/image.png" in content
        assert "Not Found for url: http://localhost:7777/image2.png" in content
        # local file should still fail
        assert "[broken] path/to/notfound" in content


